params.spec:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Audited events by real client country. Countries are colored by event volume on a log scale (the legend's title says so; the subtitle no longer does, since with one country shaded there is no legend to check it against), teal (few) through blue and purple to pink (most): the suite’s four mid-tone magnitude hues, so every step stands apart from the grey no-data countries in both themes. The gradient legend sits inside the map, over open ocean at the bottom left, labelled at the decades inside the data, and only once two or more countries are shaded - a single country has no range to read, and a 1-to-max ramp beside it matched nothing on the map. A lone country is drawn in #54B399, the teal it has as the only series of the time chart below (PALETTE[0], the first unpinned breakdown colour): a log scale over one value has no range, and it drew the country lavender, a colour that chart gives nothing. With two or more countries the colour is magnitude and the legend shows; it then cannot match the chart's categorical colours, and the panel description says so. Hover for events, identities, client IPs and share of placed traffic. The title line states how much of the stream could be placed at all, rounded once in ES|QL exactly as the Geo coverage tile is (ROUND(located / total, 3)), so the two always print the same tenth of a percent: platform-internal hops, private addresses and events with no client IP resolve to nothing, so a blank country is not evidence of no traffic. Text is 13-14px, the size of the table text beside it: at 11px the subtitle was the smallest text on the page. Unshaded land is #98A2B3 at 0.3 opacity with a 0.75 border, one mid grey that reads on both themes: at 0.14 it all but vanished on the light theme's white panel.",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "config": {
    "view": {
      "stroke": null
    },
    "legend": {
      "labelFontSize": 12,
      "titleFontSize": 12
    },
    "title": {
      "fontSize": 14,
      "fontWeight": 500,
      "anchor": "start",
      "subtitleFontSize": 13,
      "subtitlePadding": 4
    }
  },
  "title": {
    "text": {
      "expr": "length(data('coverage')) && data('coverage')[0].total > 0 ? length(data('countries')) + (length(data('countries')) == 1 ? ' country' : ' countries') + ' · placed on the map: ' + format(data('coverage')[0].share, '.1%') + ' of events · could not be placed: ' + format(1 - data('coverage')[0].share, '.1%') : 'No activity for this selection in this time range'"
    },
    "subtitle": [
      "Placed by client.ip, the real client; source.ip is only the proxy hop.",
      "Where the rest went: Geo resolution of audited events, beside the map."
    ]
  },
  "projection": {
    "type": "naturalEarth1"
  },
  "layer": [
    {
      "data": {
        "name": "world",
        "url": {
          "%type%": "emsfile",
          "name": "World Countries"
        },
        "format": {
          "type": "topojson",
          "feature": "data"
        }
      },
      "transform": [
        {
          "filter": "datum.properties.iso2 !== 'AQ'"
        }
      ],
      "mark": {
        "type": "geoshape",
        "fill": "#98A2B3",
        "fillOpacity": 0.3,
        "stroke": "#98A2B3",
        "strokeWidth": 0.5,
        "strokeOpacity": 0.75
      }
    },
    {
      "data": {
        "name": "coverage",
        "url": {
          "%type%": "esql",
          "query": "FROM logs-elastic_cloud.serverless_audit.otel-* | WHERE @timestamp <= ?_tend AND @timestamp > ?_tstart | STATS total = COUNT(*), located = COUNT(client.geo.country_iso_code) | EVAL share = ROUND(located * 1.0 / total, 3)",
          "%timefield%": "@timestamp",
          "%context%": true
        }
      },
      "mark": {
        "type": "point",
        "opacity": 0
      },
      "encoding": {
        "longitude": {
          "datum": 0
        },
        "latitude": {
          "datum": 0
        }
      }
    },
    {
      "data": {
        "name": "countries",
        "url": {
          "%type%": "esql",
          "query": "SET unmapped_fields=\"nullify\"; FROM logs-elastic_cloud.serverless_audit.otel-* | WHERE @timestamp <= ?_tend AND @timestamp > ?_tstart | WHERE client.geo.country_iso_code IS NOT NULL | EVAL actor = COALESCE(user.email, api_key.name, user.name, \"<anonymous>\") | STATS events = COUNT(*), actors = COUNT_DISTINCT(actor), ips = COUNT_DISTINCT(client.ip) BY iso = client.geo.country_iso_code, country = client.geo.country_name | SORT events DESC | LIMIT 300",
          "%timefield%": "@timestamp",
          "%context%": true
        }
      },
      "transform": [
        {
          "joinaggregate": [
            {
              "op": "sum",
              "field": "events",
              "as": "placed"
            }
          ]
        },
        {
          "calculate": "datum.events / datum.placed",
          "as": "share"
        },
        {
          "lookup": "iso",
          "from": {
            "data": {
              "url": {
                "%type%": "emsfile",
                "name": "World Countries"
              },
              "format": {
                "type": "topojson",
                "feature": "data"
              }
            },
            "key": "properties.iso2"
          },
          "as": "geo"
        },
        {
          "filter": "datum.geo != null"
        }
      ],
      "mark": {
        "type": "geoshape",
        "stroke": "#98A2B3",
        "strokeWidth": 0.5,
        "strokeOpacity": 0.8
      },
      "encoding": {
        "shape": {
          "field": "geo",
          "type": "geojson"
        },
        "color": {
          "condition": {
            "test": "length(data('countries')) < 2",
            "value": "#54B399"
          },
          "field": "events",
          "type": "quantitative",
          "scale": {
            "type": "log",
            "range": [
              "#54B399",
              "#6092C0",
              "#9170B8",
              "#D36086"
            ],
            "interpolate": "hcl"
          },
          "legend": {
            "title": "Events (log scale)",
            "orient": "bottom-left",
            "direction": "horizontal",
            "gradientLength": 140,
            "gradientThickness": 10,
            "values": {
              "expr": "!(length(data('countries')) > 1) ? [] : floor(log(domain('color')[1]) / LN10 + 1e-9) - ceil(log(domain('color')[0]) / LN10 - 1e-9) >= 1 ? slice([1, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000], ceil(log(domain('color')[0]) / LN10 - 1e-9), 1 + floor(log(domain('color')[1]) / LN10 + 1e-9)) : domain('color')"
            },
            "labelExpr": "format(datum.value, '.2~s')",
            "titleOpacity": {
              "expr": "length(data('countries')) > 1 ? 1 : 0"
            },
            "labelOpacity": {
              "expr": "length(data('countries')) > 1 ? 1 : 0"
            },
            "gradientOpacity": {
              "expr": "length(data('countries')) > 1 ? 1 : 0"
            },
            "offset": 4
          }
        },
        "tooltip": [
          {
            "field": "country",
            "title": "Country"
          },
          {
            "field": "events",
            "title": "Events",
            "format": ","
          },
          {
            "field": "share",
            "title": "Share of placed events",
            "format": ".1%"
          },
          {
            "field": "actors",
            "title": "Identities",
            "format": ","
          },
          {
            "field": "ips",
            "title": "Client IPs",
            "format": ","
          }
        ]
      }
    }
  ]
}
